"""Minimal Kura JWT REST client, meant to run inside a Kura-managed container.

This example favours readability over robustness. Comments marked "PRODUCTION:"
point out what to change before using it as the base of a real workload.
"""

import base64
import json
import os
import ssl
import sys
import time
import urllib.error
import urllib.request

IMAGES_PATH = "/inventory/v1/images"
REFRESH_PATH = "/token/jwt/v1/refresh"


# PRODUCTION: use the logging module (levels, format, handlers) instead of print, and
# make sure token values or Authorization headers are never written to the logs.
def log(message):
    print(time.strftime("%Y-%m-%d %H:%M:%S"), message, flush=True)


# PRODUCTION: validate the content ("accessToken" and "refreshToken" present) and exit
# with a clear message if the file is missing or malformed.
# The file only holds the initial token pair and is read-only: refreshed pairs live in
# memory only, so if the process restarts the initial pair may already be expired.
# Check how your deployment re-provisions credentials in that case.
def read_token_pair(path):
    with open(path, encoding="utf-8") as token_file:
        return json.load(token_file)


# The payload is decoded without verifying the signature. This is acceptable here because
# "exp" is only used to schedule the refresh: Kura still verifies the token on every
# request. Never use unverified claims for authorization decisions.
# PRODUCTION: handle malformed tokens (missing "exp", bad encoding) gracefully.
def expiration_of(token):
    payload = token.split(".")[1]
    payload += "=" * (-len(payload) % 4)
    return json.loads(base64.urlsafe_b64decode(payload))["exp"]


def ssl_context():
    # WARNING: this example is not production ready! Certificate and hostname
    # verification are disabled, which exposes the tokens to man-in-the-middle attacks.
    #
    # PRODUCTION: configure the Kura REST service with a certificate issued by a CA you
    # control, whose Subject Alternative Names include the host used in
    # KURA_REST_BASE_URL (e.g. the bridge gateway IP 172.17.0.1). Make the CA
    # certificate available to the container (baked into the image or through a
    # read-only volume mount) and return a verifying context instead, for example:
    #
    #     context = ssl.create_default_context(cafile=os.environ["KURA_CA_FILE"])
    #     context.minimum_version = ssl.TLSVersion.TLSv1_2
    #     return context
    #
    # Note: KURA_CA_FILE is not set by Kura, choose your own variable or a fixed path.
    return ssl._create_unverified_context()


class KuraClient:

    def __init__(self, base_url, token_pair, context):
        self.base_url = base_url.rstrip("/")
        self.token_pair = token_pair
        self.context = context

    def get_framework_properties(self):
        request = urllib.request.Request(self.base_url + IMAGES_PATH, headers={
            "Authorization": "Bearer " + self.token_pair["accessToken"],
            "Accept": "application/json",
        })
        # PRODUCTION: always pass a timeout to urlopen (e.g. timeout=10), otherwise a
        # stalled connection blocks the client forever.
        with urllib.request.urlopen(request, context=self.context) as response:
            return json.load(response)

    # PRODUCTION:
    # - pass a timeout and retry transient failures (network errors, HTTP 5xx) with
    #   exponential backoff, for as long as the refresh token is still valid;
    # - validate the response before replacing the current pair, so that a bad response
    #   does not discard a still-valid refresh token;
    # - if the client becomes multi-threaded, guard the refresh with a lock so that only
    #   one refresh request is in flight at a time.
    def refresh(self):
        request = urllib.request.Request(self.base_url + REFRESH_PATH, method="POST",
                                         data=self.token_pair["refreshToken"].encode("utf-8"),
                                         headers={"Content-Type": "text/plain", "Accept": "application/json"})
        with urllib.request.urlopen(request, context=self.context) as response:
            self.token_pair = json.load(response)

    def access_token_expires_within(self, seconds):
        return expiration_of(self.token_pair["accessToken"]) - time.time() < seconds


def main():
    base_url = os.environ["KURA_REST_BASE_URL"]
    jwt_file = os.environ["KURA_JWT_FILE"]
    # PRODUCTION: validate the required variables above and exit with a clear message if
    # they are missing, and read the tunables below from the environment.
    # The expiration check runs once per iteration, so refresh_margin must be larger
    # than interval plus the worst-case refresh time (timeouts and retries included),
    # otherwise the access token can expire between two iterations.
    interval = 10
    refresh_margin = 15

    log("Identity: " + os.environ.get("KURA_IDENTITY_NAME", "?") + ", REST base URL: " + base_url)
    client = KuraClient(base_url, read_token_pair(jwt_file), ssl_context())

    # PRODUCTION: install a SIGTERM handler (signal.signal) that stops the loop cleanly.
    # The client runs as PID 1 in the container, where SIGTERM is ignored unless a
    # handler is installed, so "docker stop" would otherwise wait for its timeout and
    # then SIGKILL the process. Waiting on a threading.Event instead of time.sleep lets
    # the handler interrupt the wait immediately.
    while True:
        try:
            if client.access_token_expires_within(refresh_margin):
                client.refresh()
                log("Token pair refreshed")

            properties = client.get_framework_properties()
            # PRODUCTION: avoid dumping full responses at the default log level.
            log("Images:\n" + json.dumps(properties, indent=2, sort_keys=True))
        # PRODUCTION: handle each error class explicitly:
        # - 401: the token was rejected. Attempting a single refresh before giving up
        #   covers a token rejected earlier than expected; if the refresh is rejected too,
        #   the identity is no longer valid and exiting is the right choice;
        # - 403: the identity lacks a permission (see "Container Permissions"), retrying
        #   will not help;
        # - 429 and 5xx: transient, retry with backoff.
        # Exiting with a non-zero status makes the failure visible to the container
        # runtime: pair it with a suitable restart policy and alerting.
        except urllib.error.HTTPError as e:
            log("Request failed: HTTP " + str(e.code) + " " + e.reason)
            if e.code == 401:
                log("Access to the Kura APIs lost, exiting")
                return 1
        except urllib.error.URLError as e:
            # PRODUCTION: back off (exponential, with jitter) instead of retrying at a
            # fixed interval, and report prolonged outages (health check, metrics).
            log("Request failed: " + str(e.reason))
        # PRODUCTION: also catch unexpected errors (e.g. invalid JSON in a response) and
        # log them with the traceback, so that a single bad response does not crash the
        # client.

        time.sleep(interval)


if __name__ == "__main__":
    sys.exit(main())
